(function(){
 const page=location.pathname.split('/').pop();
 const kind=page==='index.html'?'detail':page==='product-suite.html'?'suite':page==='product-video.html'?'video':null;
 if(!kind)return;
 const labels={detail:'商品详情长图',suite:'商品套图',video:'商品生视频'};
 const key='fashmaker-prototype-task-history-v2';
 const style=document.createElement('style');style.textContent=`.task-history-open,.task-new{border:1px solid #59675d;background:#253129;color:#eff8f0;border-radius:9px;padding:8px 12px;font:inherit;cursor:pointer}.task-new{background:#d7f5e1;color:#10231a;border:0}.task-history-shade{position:fixed;inset:0;background:#0009;z-index:100;display:none}.task-history-shade.open{display:block}.task-history-drawer{position:fixed;right:0;top:0;bottom:0;width:min(590px,100vw);z-index:101;background:#191c1a;color:#f2f4f2;box-shadow:-20px 0 70px #0009;transform:translateX(105%);transition:transform .2s;overflow:auto;padding:22px;font:13px/1.5 -apple-system,BlinkMacSystemFont,'PingFang SC',sans-serif}.task-history-drawer.open{transform:none}.task-history-drawer header{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:18px}.task-history-drawer h2{margin:0;font-size:22px}.task-history-drawer button{cursor:pointer}.task-history-close,.task-history-back{background:#2b302c;border:1px solid #485149;color:#fff;border-radius:8px;padding:7px 11px}.task-history-row{display:block;width:100%;text-align:left;background:#222723;border:1px solid #394239;color:#fff;border-radius:12px;padding:14px;margin:10px 0}.task-history-row:hover{border-color:#61c88a}.task-history-row strong,.task-history-row small{display:block}.task-history-row small{color:#a5afa7;margin-top:5px}.task-history-head{display:flex;gap:14px;align-items:center}.task-history-head img{width:70px;height:70px;object-fit:cover;border-radius:8px}.task-history-fields{display:grid;grid-template-columns:1fr 1fr;gap:9px}.task-history-fields div{background:#252b26;border-radius:8px;padding:9px;min-width:0}.task-history-fields dt{font-size:11px;color:#95a498}.task-history-fields dd{margin:4px 0 0;white-space:pre-wrap;overflow-wrap:anywhere}.task-history-output{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.task-history-output figure{margin:0;background:#242a25;border-radius:8px;overflow:hidden}.task-history-output img{width:100%;height:130px;object-fit:cover}.task-history-visual{height:140px;overflow:hidden}.task-history-visual .suite-art{height:140px!important;margin:0!important}.task-history-visual .prompt-image{height:140px}.task-history-output figcaption{padding:7px;font-size:11px}.task-history-drawer h3{margin:22px 0 10px;font-size:15px}.task-history-drawer details{border:1px solid #394239;border-radius:8px;margin:7px 0;padding:9px}.task-history-drawer details div{white-space:pre-wrap;color:#c6d0c7;margin-top:7px}.task-history-repeat{width:100%;background:#d7f5e1;color:#10231a;border:0;border-radius:9px;padding:11px;margin-top:20px;font-weight:650}`;document.head.append(style);
 const shade=document.createElement('div');shade.className='task-history-shade';const drawer=document.createElement('aside');drawer.className='task-history-drawer';drawer.setAttribute('aria-label','生成历史');drawer.innerHTML='<header><h2>生成历史</h2><button class="task-history-close">关闭</button></header><div class="task-history-content"></div>';document.body.append(shade,drawer);const content=drawer.querySelector('.task-history-content');function close(){shade.classList.remove('open');drawer.classList.remove('open')}function open(){shade.classList.add('open');drawer.classList.add('open');list()}shade.onclick=close;drawer.querySelector('.task-history-close').onclick=close;
 function db(){return new Promise((resolve,reject)=>{const request=indexedDB.open(key,1);request.onupgradeneeded=()=>request.result.createObjectStore('tasks',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
 async function all(){try{const database=await db();return await new Promise((resolve,reject)=>{const t=database.transaction('tasks','readonly');const r=t.objectStore('tasks').getAll();r.onsuccess=()=>{database.close();resolve(r.result.filter(x=>x.kind===kind).sort((a,b)=>b.createdAt-a.createdAt))};r.onerror=()=>reject(r.error)})}catch{try{return JSON.parse(localStorage.getItem(key)||'[]').filter(x=>x.kind===kind).sort((a,b)=>b.createdAt-a.createdAt)}catch{return []}}}
 async function put(record){try{const database=await db();return await new Promise((resolve,reject)=>{const t=database.transaction('tasks','readwrite');t.objectStore('tasks').put(record);t.oncomplete=()=>{database.close();resolve()};t.onerror=()=>reject(t.error)})}catch{const records=JSON.parse(localStorage.getItem(key)||'[]');records.unshift(record);localStorage.setItem(key,JSON.stringify(records.slice(0,20)))}}
 function fields(){return [...document.querySelectorAll('.config input,.config select,.config textarea')].filter(x=>x.id&&x.type!=='file').map(x=>({id:x.id,value:x.type==='checkbox'?x.checked:x.value}))}
 function fieldLabel(id){const input=document.getElementById(id);return document.querySelector(`label[for="${id}"]`)?.textContent.trim()||input?.closest('.section,.field')?.querySelector('label,.section-head label')?.textContent.trim()||id}
 function selectedSettings(){return fields().map(x=>({label:fieldLabel(x.id),value:String(x.value)}))}
 function snapshot(){const base={id:Date.now()+'-'+Math.random().toString(36).slice(2,7),kind,createdAt:Date.now(),productId:kind==='video'?currentProduct?.id||null:window.FashLinkedProduct?.id||null,productName:kind==='video'?currentProduct?.name||'':window.FashLinkedProduct?.name||'',title:kind==='video'?(document.getElementById('productName').value.trim()||'未命名商品')+' · 商品生视频':((kind==='suite'?assets[0]?.name:images[0]?.name)||'未命名商品')+' · '+labels[kind],fields:fields(),settings:selectedSettings(),images:[],outputs:[],prompts:[],extras:{}};
 if(kind==='detail'){base.images=images.map(x=>({...x}));base.outputs=prompts.filter(x=>x.selected&&x.generated).map(x=>({title:x.title,src:images[0]?.src||photoHead,visualHtml:document.querySelector('.image-result')?.innerHTML||''}));base.prompts=prompts.map(x=>({title:x.title,text:x.text,selected:x.selected}));base.extras={activeMode,selectedStyle,customDirection:document.getElementById('customDirection').value}}
 if(kind==='suite'){base.images=assets.map(x=>({...x}));base.outputs=results.map((x,i)=>({title:x.title,kindId:x.kind.id,src:assets[0]?.src||productPhoto,visualHtml:document.querySelectorAll('.suite-result')[i]?.querySelector('.suite-art')?.outerHTML||''}));base.prompts=prompts.map(x=>({title:x.title,text:x.text,selected:x.selected}));base.extras={activeStyleMode,selectedStyle,selectedTypes:[...selectedTypes],quantities:{...quantities},styleReference:document.getElementById('styleFileName').textContent}}
 if(kind==='video'){base.images=images.map((src,i)=>({src,name:'商品图 '+(i+1)}));base.outputs=[{title:'视频演示预览',src:images[0],video:true}];base.prompts=shots.map((x,i)=>({title:'镜头 '+(i+1),text:x.text}));base.extras={personImage,mode,narration,selectedVoice,model:document.getElementById('model').value,sellingPoints:points()}}
 return base}
 async function durableUrl(src){if(!src?.startsWith('blob:'))return src;try{const response=await fetch(src);const blob=await response.blob();return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob)})}catch{return src}}
 async function save(){showNew();try{const record=snapshot();const srcMap=new Map();for(const image of record.images){const original=image.src;image.src=await durableUrl(original);srcMap.set(original,image.src)}for(const output of record.outputs){output.src=srcMap.get(output.src)||await durableUrl(output.src);for(const [from,to] of srcMap)if(output.visualHtml&&from!==to)output.visualHtml=output.visualHtml.replaceAll(from,to)}if(record.extras?.personImage)record.extras.personImage=await durableUrl(record.extras.personImage);await put(record);showNew();return record}catch(error){console.warn('历史任务保存失败',error);alert('历史任务保存失败，请检查浏览器存储空间')}}
 function showNew(){if(kind==='video')return;let button=document.getElementById('newSingleTask');if(!button){button=document.createElement('button');button.id='newSingleTask';button.className='task-new';button.textContent=kind==='detail'?'新建详情图':'新建套图';document.querySelector('.results-actions')?.append(button)}button.hidden=false;button.onclick=()=>reset(false)}
 function reset(keepSettings){window.FashLinkedProduct=null;if(kind==='video'){document.getElementById('newVideo').click();return}
 if(kind==='detail'){images.splice(0);viewStage='examples';prompts.forEach((p,i)=>{p.selected=false;p.generated=false;p.text=basePromptTexts[i]});document.getElementById('generate').disabled=false;document.getElementById('generate').innerHTML='生成长图提示词';document.getElementById('generateHint').textContent='先生成整张详情长图的提示词，再选择一个方案';document.getElementById('outputSettings').classList.remove('is-locked');document.getElementById('dimensions').disabled=false;document.getElementById('clarity').disabled=false;document.getElementById('statusTag').textContent='待开始';document.getElementById('promptToolbar').hidden=true;renderUploads();renderThumbs();renderResults()}
 if(kind==='suite'){assets.length=0;prompts.length=0;results.length=0;stage='examples';document.querySelectorAll('#suiteForm input,#suiteForm select,#suiteForm textarea,#suiteForm button').forEach(x=>x.disabled=false);document.getElementById('generatePrompts').disabled=false;document.getElementById('generatePrompts').innerHTML='生成套图方案';document.getElementById('generateHint').textContent='选择图片类型后，先生成并检查每张图的提示词';document.getElementById('promptToolbar').hidden=true;renderUploads();render()}
 document.getElementById('newSingleTask').hidden=true;if(!keepSettings)window.scrollTo({top:0,behavior:'smooth'})}
 function restore(record){reset(true);window.FashLinkedProduct=record.productId?{id:record.productId,name:record.productName}:null;for(const field of record.fields||[]){const element=document.getElementById(field.id);if(!element)continue;if(element.type==='checkbox')element.checked=field.value;else element.value=field.value;element.dispatchEvent(new Event('change',{bubbles:true}))}
 if(kind==='detail'){images.push(...(record.images||[]));activeMode=record.extras?.activeMode||'trending';selectedStyle=record.extras?.selectedStyle||selectedStyle;document.getElementById('customDirection').value=record.extras?.customDirection||'';document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x.dataset.mode===activeMode));document.getElementById('trendingPane').hidden=activeMode==='custom';document.getElementById('customPane').hidden=activeMode!=='custom';document.querySelectorAll('[data-style]').forEach(x=>x.classList.toggle('selected',x.dataset.style===selectedStyle));renderUploads();renderThumbs();renderResults()}
 if(kind==='suite'){assets.push(...(record.images||[]));activeStyleMode=record.extras?.activeStyleMode||'recommended';selectedStyle=record.extras?.selectedStyle||selectedStyle;selectedTypes.clear();(record.extras?.selectedTypes||[]).forEach(x=>selectedTypes.add(x));Object.assign(quantities,record.extras?.quantities||{});document.getElementById('styleFileName').textContent=record.extras?.styleReference||'未添加参考图';document.querySelectorAll('[data-style-mode]').forEach(x=>x.classList.toggle('active',x.dataset.styleMode===activeStyleMode));document.getElementById('recommendedStylePane').hidden=activeStyleMode==='custom';document.getElementById('customStylePane').hidden=activeStyleMode!=='custom';document.querySelectorAll('[data-style]').forEach(x=>x.classList.toggle('selected',x.dataset.style===selectedStyle));renderUploads();renderTypes();render()}
 if(kind==='video'){currentProduct=record.productId?{id:record.productId,name:record.productName}:null;images=(record.images||[]).map(x=>x.src);personImage=record.extras?.personImage||'';mode=record.extras?.mode||'preset';selectedVoice=record.extras?.selectedVoice||null;setNarration(record.extras?.narration||'off');document.getElementById('voiceSelectLabel').textContent=selectedVoice?.name||'选择口播音色';document.getElementById('personPreview').innerHTML=personImage?'<img src="'+personImage+'" alt="人物参考图">':'';document.getElementById('selectedProduct').hidden=!images.length;if(images.length)document.getElementById('selectedProduct').textContent='已载入 '+images.length+' 张商品图片';document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('selected',x.dataset.mode===mode));document.getElementById('presetBox').hidden=mode!=='preset';document.getElementById('customBox').hidden=mode!=='custom';document.getElementById('sellingPoints').replaceChildren();(record.extras?.sellingPoints||[]).forEach(x=>addPoint(x));validate()}
 close()}
 function node(tag,text){const element=document.createElement(tag);element.textContent=text??'';return element}
 async function list(){const records=await all();content.replaceChildren();if(!records.length){content.append(node('p','暂无生成历史。完成一次生成后，这里会保存完整参数和结果。'));return}for(const record of records){const button=node('button');button.className='task-history-row';button.append(node('strong',record.title),node('small',new Date(record.createdAt).toLocaleString('zh-CN')+' · '+record.outputs.length+' 个结果'));button.onclick=()=>detail(record);content.append(button)}}
 function detail(record){content.replaceChildren();const back=node('button','← 返回任务列表');back.className='task-history-back';back.onclick=list;content.append(back,node('h3',record.title),node('p',new Date(record.createdAt).toLocaleString('zh-CN')));const output=node('div');output.className='task-history-output';(record.outputs||[]).forEach(item=>{const figure=node('figure'),img=document.createElement('img');img.src=item.src||'';img.alt=item.title||'生成结果';if(item.visualHtml){const visual=node('div');visual.className='task-history-visual';visual.innerHTML=item.visualHtml;figure.append(visual)}else figure.append(img);figure.append(node('figcaption',item.title+(item.video?' · 视频演示封面':'')));output.append(figure)});content.append(node('h3','生成结果'),output,node('h3','本次设置'));const dl=node('dl');dl.className='task-history-fields';(record.settings||[]).forEach(field=>{const box=node('div');box.append(node('dt',field.label),node('dd',field.value));dl.append(box)});for(const [label,value] of Object.entries(record.extras||{})){const box=node('div');box.append(node('dt',label),node('dd',typeof value==='string'?value:JSON.stringify(value)));dl.append(box)}content.append(dl,node('h3','输入商品图'));const refs=node('div');refs.className='task-history-output';(record.images||[]).forEach(image=>{const figure=node('figure'),img=document.createElement('img');img.src=image.src;figure.append(img,node('figcaption',image.name||'商品图'));refs.append(figure)});content.append(refs,node('h3','生成内容'));(record.prompts||[]).forEach(item=>{const d=node('details'),summary=node('summary',item.title);d.append(summary,node('div',item.text));content.append(d)});const repeat=node('button','以此任务再次生成');repeat.className='task-history-repeat';repeat.onclick=()=>restore(record);content.append(repeat)}
 const historyButton=document.getElementById('historyBtn');if(historyButton)historyButton.onclick=open;
 window.PrototypeTaskHistory={save,open,reset};
})();
